def transform(grid):
    n=0
    for line in list(grid)+list(zip(*grid)):
        prev=0
        length=0
        for x in list(line)+[0]:
            if x==prev and x!=0:
                length+=1
            else:
                if prev!=0 and length>=3:
                    n+=1
                prev=x
                length=1 if x else 0
    return [[3]*n]

